// NURA 04 - build one WhatsApp message per due follow-up.
// in_window = customer wrote in the last 23h -> normal text; otherwise approved template "nura_followup".
const out = [];
for (const it of $input.all()) {
  const r = it.json || {};
  if (!r.id) continue;
  const phone = String(r.phone || '').replace(/\D/g, '');
  const uid = (!phone && String(r.session_id || '').startsWith('wa:u.')) ? String(r.session_id).slice(5) : '';
  if (!phone && !uid) continue;
  const first = (String(r.name || '').trim().split(/\s+/)[0] || '').replace(/[^\p{L}\p{N}'-]/gu, '') || 'there';
  const product = String(r.product_name || '').trim();
  const price = r.product_price ? Number(String(r.product_price).replace(/[^\d.]/g, '')) : 0;
  const priceTxt = price ? 'KSh ' + Math.round(price).toLocaleString('en-US') : '';
  const to = phone ? { to: phone } : { recipient: uid };
  let payload, mode;
  if (r.in_window) {
    const lines = ['Hi ' + first + ', this is NURA Beauty checking in.'];
    if (product) lines.push('You asked about the ' + product + (priceTxt ? ' (' + priceTxt + ')' : '') + '. It is still available' + (r.product_url ? ': ' + r.product_url : '.'));
    lines.push('Would you like us to reserve it for you? Reply here and we will help you order. You can pay by M-Pesa Till 1679269 or at checkout on our website.');
    payload = { messaging_product: 'whatsapp', recipient_type: 'individual', ...to, type: 'text', text: { preview_url: true, body: lines.join('\n') } };
    mode = 'text';
  } else {
    payload = { messaging_product: 'whatsapp', recipient_type: 'individual', ...to, type: 'template',
      template: { name: 'nura_followup', language: { code: 'en' }, components: [{ type: 'body', parameters: [
        { type: 'text', text: first },
        { type: 'text', text: product || 'wig you were looking at' },
        { type: 'text', text: priceTxt || 'the price shown on our website' },
      ] }] } };
    mode = 'template';
  }
  out.push({ json: { id: r.id, mode, body: JSON.stringify(payload) } });
}
return out;

// Pair each WhatsApp API response with its follow-up and build the mark payload.
const src = $('Build Message').all();
return $input.all().map((it, i) => {
  const r = it.json || {};
  const s = (src[i] || src[0]).json || {};
  const code = Number(r.statusCode || 0);
  const b = (r.body && typeof r.body === 'object') ? r.body : {};
  const wamid = (b.messages && b.messages[0] && b.messages[0].id) || '';
  const ok = code >= 200 && code < 300 && !!wamid;
  const err = b.error ? ((b.error.code || '') + ' ' + (b.error.message || '')).trim() : (ok ? '' : 'HTTP ' + code);
  const p = { id: s.id, ok, wamid, result: ok ? 'sent ' + s.mode : 'failed ' + s.mode + ': ' + err };
  return { json: { p_json: JSON.stringify(p).replace(/\$/g, '\\u0024') } };
});

// Owner's morning list to 0703 201 241. Text if the owner wrote to the business in the last 23h, else template "nura_owner_digest".
const OWNER = '254703201241';
const d = $input.first().json || {};
if (Number(d.sent_count || 0) === 0 && Number(d.needs_count || 0) === 0) return [];
let payload;
if (d.owner_in_window) {
  const body = ('NURA follow-ups - ' + d.today + '\nSent automatically: ' + d.sent_count + '\nNeed you: ' + d.needs_count + '\n\n' + (d.lines || '')).slice(0, 4000);
  payload = { messaging_product: 'whatsapp', recipient_type: 'individual', to: OWNER, type: 'text', text: { body } };
} else {
  const flat = (String(d.lines || '').replace(/\s*\n\s*/g, '; ').replace(/\s{2,}/g, ' ').slice(0, 700)) || 'none';
  payload = { messaging_product: 'whatsapp', recipient_type: 'individual', to: OWNER, type: 'template',
    template: { name: 'nura_owner_digest', language: { code: 'en' }, components: [{ type: 'body', parameters: [
      { type: 'text', text: String(d.today) }, { type: 'text', text: String(d.sent_count) },
      { type: 'text', text: String(d.needs_count) }, { type: 'text', text: flat },
    ] }] } };
}
return [{ json: { body: JSON.stringify(payload) } }];
